insert into profiles (id, owner_user_id, type, handle, display_name, bio, i18n, avatar_url, banner_url, is_verified, verified_at) select '6fe5accc-5561-556a-99d1-8dd899d501fe', id, 'creator', 'dropolis', 'Dropolis', 'A delivery city builder. Pack online orders, send couriers to every door, build your own streets and grow a tiny town into a city, then a colony on Mars.', '{"bio":{"en":"A delivery city builder. Pack online orders, send couriers to every door, build your own streets and grow a tiny town into a city, then a colony on Mars.","es":"Un juego de construir ciudades a base de repartos. Prepara pedidos, envía repartidores a cada puerta, traza tus calles y convierte un pueblo en una ciudad y luego en una colonia en Marte.","tr":"Teslimatla büyüyen bir şehir kurma oyunu. Siparişleri paketle, kuryeleri her kapıya gönder, sokaklarını kendin çiz ve küçük bir kasabayı şehre, sonra Mars''ta bir koloniye dönüştür."},"kind":{"en":"Indie game","es":"Juego indie","tr":"Bağımsız oyun"},"mono":null}', 'https://promovote.com/media/dropolis-icon.jpg', 'https://promovote.com/media/dropolis-poster.jpg', 1, strftime('%Y-%m-%dT%H:%M:%fZ', 'now') from "user" where id = '99033ba0-caaa-538f-a632-f40df3da673a' and not exists (select 1 from profiles where handle = 'dropolis') on conflict do nothing;
