insert into profiles (id, owner_user_id, type, handle, display_name, bio, i18n, avatar_url, banner_url, is_verified, verified_at) select 'e164040f-1db0-5712-87fe-7d9acf817628', id, 'creator', 'dovelet', 'Dovelet', 'A couple widget for long distance and close relationships. Their latest note on your home screen, a touch that buzzes their phone, shared photos and a heart flower you grow together. No location tracking.', '{"bio":{"en":"A couple widget for long distance and close relationships. Their latest note on your home screen, a touch that buzzes their phone, shared photos and a heart flower you grow together. No location tracking.","es":"Un widget para parejas, a distancia o cerca. Su última nota en tu pantalla de inicio, un toque que hace vibrar su teléfono, fotos compartidas y una flor que crecen juntos. Sin rastreo de ubicación.","tr":"Uzak ya da yakın çiftler için bir widget. Sevgilinin son notu ana ekranında, telefonunu titreten bir dokunuş, ortak fotoğraflar ve birlikte büyüttüğünüz bir kalp çiçeği. Konum takibi yok."},"kind":{"en":"Couples app","es":"App para parejas","tr":"Çiftler için uygulama"},"mono":null}', 'https://promovote.com/media/dovelet-icon.jpg', 'https://promovote.com/media/dovelet-poster.jpg', 1, strftime('%Y-%m-%dT%H:%M:%fZ', 'now') from "user" where id = '0aa15128-281e-51a1-8c66-d7c05b510953' and not exists (select 1 from profiles where handle = 'dovelet') on conflict do nothing;
