insert into promos (id, creator_profile_id, slug, lang, title, description, i18n, status, cta_kind, cta_url, cta_safety_status, has_perk, rights_confirmed_at, submitted_at, approved_at, live_at) select '8209cd26-413a-5a62-ada2-251c46eaf35b', id, 'hauling-empire-run-the-company', 'en', 'You don''t drive. You run the company.', 'Start with one van, plan routes on land and sea and hire your team. No gems, no energy bars.', '{"title":{"en":"You don''t drive. You run the company.","es":"No conduces. Diriges la empresa.","tr":"Direksiyonda sen yoksun. Şirketi sen yönetiyorsun."},"desc":{"en":"Start with one van, plan routes on land and sea and hire your team. No gems, no energy bars.","es":"Empieza con una furgoneta, planifica rutas por tierra y mar y contrata a tu equipo. Sin gemas ni barras de energía.","tr":"Tek bir kamyonetle başla, karada ve denizde rota planla, ekibini kur. Elmas yok, enerji barı yok."}}', 'live', 'app_store', 'https://apps.apple.com/us/app/hauling-empire-truck-tycoon/id6815224121', 'safe', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now') from profiles where handle = 'haulingempire' on conflict do nothing;
